CThingList::SNode g_nodes[N + 1];
bool useSecond;

static bool Expected(const CThing& t)
{
    return (t.StateBits & 4) && (t.StateBits & 8) && !(t.StateBits & 1) && !(t.StateBits & 0x20) && (t.ThingTypeFlags & CThing::ThingTypeMask) == CThing::ThingTypeMask && ((((t.Accept >> 0) & 1) != 0) && (((t.Accept >> 1) & 1) != 0));
