    tools.AllThings = &list; tools.TypeList = &list; tools.LastType = -1;
    CThingFilter_HasTC filt2 = { 0 };
    CThingFilter_InRegion filt3 = { 1 };
    CFilter_Bind2<CThingFilter_HasTC, CThingFilter_InRegion > filt1 = { filt2, filt3 };
