    CTCEntityEventsMethods list;
    list.List._M_node = head;
    NEntityEvents::CIsEventOfType filter = { 0x19 };
    NEntityEvents::CIsEventOfType other = { 0x1a };

    NEntityEvents::CEventVillagerInteraction* found = 0;
    bool ok = list.GetEvent(&found, filter);
    const CTestEvent* want = 0;
    for (i = N - 1; i >= 0; --i)
        if (Expected(g_events[i])) { want = &g_events[i]; break; }
    int bad = 0;
    if (!want || !ok || (const void*)found != (const void*)want) bad = 1;
    NEntityEvents::CEventVillagerInteraction* untouched = (NEntityEvents::CEventVillagerInteraction*)&g_attacker;
    found = untouched;
    bool ok2 = list.GetEvent(&found, other);
    if (ok2 || found != untouched) bad = 1;
    for (i = 0; i < N; ++i)
        if (g_infos[i]->RefCount != 1) bad = 1;
    if (g_deleted != 0) bad = 1;
    if (bad) { std::printf("00982610_TEST FAIL\n"); return 1; }
    std::printf("00982610_TEST PASS\n");
    return 0;
}
